const rad=Math.PI/180;
export function lonLatToVector([lon,lat],radius=1){const c=Math.cos(lat*rad);return [radius*c*Math.cos(lon*rad),radius*Math.sin(lat*rad),-radius*c*Math.sin(lon*rad)]}
export function vectorToLonLat([x,y,z]){const r=Math.hypot(x,y,z);return [Math.atan2(-z,x)/rad,Math.asin(Math.max(-1,Math.min(1,y/r)))/rad]}
export function arcPoint(from,to,t,height=.16){const a=lonLatToVector(from),b=lonLatToVector(to);const dot=Math.max(-1,Math.min(1,a.reduce((s,v,i)=>s+v*b[i],0)));let v;if(dot>.999999){v=a.map((x,i)=>x+(b[i]-x)*t)}else if(dot<-.999999){let o=Math.abs(a[1])<.9?[-a[2],0,a[0]]:[0,a[2],-a[1]];const n=Math.hypot(...o);o=o.map(x=>x/n);v=a.map((x,i)=>x*Math.cos(Math.PI*t)+o[i]*Math.sin(Math.PI*t))}else{const theta=Math.acos(dot),s=Math.sin(theta);v=a.map((x,i)=>(x*Math.sin((1-t)*theta)+b[i]*Math.sin(t*theta))/s)}const n=Math.hypot(...v),r=1.008+Math.sin(Math.PI*t)*(height-.008);return v.map(x=>x/n*r)}
export function yearState(war,year,campaigns={}){const active=year>=war.start&&year<=war.end;const data=campaigns[war.id]||{},events=data.events||war.events;if(!active)return {active:false,current:[],past:[],routes:[],title:'本年未处于该战争时段',summary:'',pos:war.pos};const current=events.filter(e=>e.date===year),past=events.filter(e=>e.date<year),phase=data.years?.[year];return {active:true,current,past,routes:(data.routes||[]).filter(r=>r.year===year),title:phase?.[0]|| (current.length?'本年关键节点':'战争持续'),summary:phase?.[1]|| (current.length?current.map(e=>e.name).join(' · '):'当前资料未收录这一年的具体战役；淡色点为此前节点，不代表战线仍停留在那里。'),pos:phase?.[2]||current[0]?.pos||war.pos,source:data.source||war.url}}
